<?php $pages=max(1,(int)ceil($total/$perPage));if($pages>1):?><nav class="pagination" aria-label="Pagination"><span>Page <?=$page?> of <?=$pages?> · <?=$total?> records</span><div class="actions"><?php if($page>1):?><a class="button secondary tiny" href="?<?=e(http_build_query(array_replace(request()->query(),['page'=>$page-1])))?>">← Previous</a><?php endif?><?php if($page<$pages):?><a class="button secondary tiny" href="?<?=e(http_build_query(array_replace(request()->query(),['page'=>$page+1])))?>">Next →</a><?php endif?></div></nav><?php endif?>
